target.css:
:root {
  --ink: #1f2830;
  --muted: #69747b;
  --paper: #fffdf7;
  --line: #d9d7cc;
  --navy: #284f68;
  --navy-dark: #163449;
  --clay: #c7654d;
  --oat: #e8c978;
  --mint: #c8dfd1;
  --soft-blue: #e7f0f1;
  --soft-clay: #f8e5dd;
  --white: #ffffff;
}

* { box-sizing: border-box; }

.loom-card {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.title-block p,
.panel-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  line-height: 1.2;
  text-transform: uppercase;
}

.title-block h1 {
  margin: 4px 0 0;
  font-size: 21px;
  line-height: 1;
  letter-spacing: -0.5px;
}

.run-status {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 9px;
  color: var(--navy-dark);
  background: var(--mint);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.run-status i {
  width: 7px;
  height: 7px;
  background: var(--navy);
  border-radius: 50%;
}

.dashboard {
  display: grid;
  grid-template-columns: 142px 1fr;
  min-height: 174px;
}

.warp-panel {
  padding: 16px;
  background: var(--soft-blue);
  border-right: 1px solid var(--line);
}

.warp-panel > strong {
  display: block;
  margin-top: 8px;
  color: var(--navy-dark);
  font-size: 24px;
  line-height: 1;
  letter-spacing: -1px;
}

.warp-panel small {
  color: var(--muted);
  font-size: 11px;
  letter-spacing: 0;
}

.tension-bar {
  height: 7px;
  margin: 12px 0 15px;
  overflow: hidden;
  background: var(--white);
  border-radius: 999px;
}

.tension-bar span {
  display: block;
  width: 78%;
  height: 100%;
  background: var(--navy);
  border-radius: inherit;
}

.settings {
  display: grid;
  gap: 8px;
  margin: 0;
}

.settings div {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
}

.settings dt { color: var(--muted); }
.settings dd { margin: 0; font-weight: 700; }

.pattern-panel { padding: 13px 15px 11px; }

.pattern-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

.pattern-heading h2 {
  margin: 3px 0 0;
  font-size: 16px;
  line-height: 1.1;
}

.repeat-badge {
  padding: 4px 6px;
  color: var(--clay);
  background: var(--soft-clay);
  border-radius: 5px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.weave-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 2px;
  height: 52px;
  margin: 10px 0;
  padding: 3px;
  background: var(--navy-dark);
  border-radius: 6px;
}

.weave-grid span { background: var(--oat); }
.weave-grid span:nth-child(3n),
.weave-grid span:nth-child(7n) { background: var(--clay); }
.weave-grid span:nth-child(5n) { background: var(--navy); }

.yarn-list {
  display: flex;
  gap: 12px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.yarn-list li {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--muted);
  font-size: 10px;
  white-space: nowrap;
}

.yarn-list em {
  color: var(--ink);
  font-style: normal;
  font-weight: 700;
}

.swatch {
  width: 8px;
  height: 8px;
  border-radius: 2px;
}

.swatch.navy { background: var(--navy); }
.swatch.clay { background: var(--clay); }
.swatch.oat { background: var(--oat); }

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 16px;
  color: var(--muted);
  border-top: 1px solid var(--line);
  font-size: 12px;
}

.card-footer strong { color: var(--ink); }

button {
  padding: 7px 11px;
  color: var(--white);
  background: var(--navy-dark);
  border: 0;
  border-radius: 7px;
  font: inherit;
  font-size: 11px;
  font-weight: 700;
}

